arguments.cmd:
cd /app/output && npm init -y >/dev/null 2>&1 && npm i mermaid@11 @svgdotjs/svg.js svgdom sharp >/dev/null 2>&1 && cat > render.mjs <<'EOF'
import fs from 'fs';
import mermaid from 'mermaid';
import sharp from 'sharp';

const mmd = fs.readFileSync('/app/output/chart.mmd', 'utf8');
mermaid.initialize({ startOnLoad: false, theme: 'base', securityLevel: 'loose' });
const { svg } = await mermaid.render('chart1', mmd);
await sharp(Buffer.from(svg)).png({ quality: 100 }).toFile('/app/output/result.png');
EOF
node /app/output/render.mjs && file /app/output/result.png

